		return errors.New("ledger: entry needs an id")
	}
	if e.Account == "" {
		return errors.New("ledger: entry needs an account")
	}
	if _, dup := l.seen[e.ID]; dup {
		return ErrDuplicate
	}
	if len(l.entries) >= MaxEntries {
		return ErrFull
	}
	if e.Currency == "" {
		e.Currency = DefaultCurrency
	}
