6	)
7	
8	// FormatAmount renders minor units as a decimal string with the currency code.
9	func FormatAmount(amount int64, currency string) string {
10		sign := ""
11		if amount < 0 {
12			sign = "-"
13			amount = -amount
14		}
15		return fmt.Sprintf("%s%d.%02d %s", sign, amount/100, amount%100, currency)
16	}
17	
18	// FormatEntry renders one entry on a single line.
19	func FormatEntry(e Entry) string {
20		memo := e.Memo
21		if memo == "" {
22			memo = "-"
23		}
24		return fmt.Sprintf("%-12s %-10s %14s %-10s %s", e.ID, e.Account, FormatAmount(e.Amount, e.Currency), e.Category, memo)
25	}
26	
27	// FormatStatement renders every entry of an account followed by its balance.
28	func FormatStatement(l *Ledger, account string) string {
29		var b strings.Builder
30		for _, e := range l.Entries() {
31			if e.Account == account {
32				b.WriteString(FormatEntry(e))
33				b.WriteByte('\n')
34			}
35		}
36		fmt.Fprintf(&b, "balance %s\n", FormatAmount(l.Balance(account), DefaultCurrency))
37		return b.String()
38	}
