	l := sample()
	if err := Transfer(l, "t1", "cash", "savings", 500); err != nil {
		t.Fatal(err)
	}
	if l.Balance("cash") != 7000 || l.Balance("savings") != 5500 {
		t.Fatalf("balances after transfer: cash=%d savings=%d", l.Balance("cash"), l.Balance("savings"))
	}
