// has a real failure to report.
func TestFormatAmountNegative(t *testing.T) {
	if got := FormatAmount(-5, "USD"); got != "-0.05 USD" {
		t.Fatalf("FormatAmount(-5) = %q, want -0.05 USD", got)
	}
}

